import{_ as o,o as i,c as t,a0 as a}from"./chunks/framework.DmGDJU50.js";const g=JSON.parse('{"title":"Decisions","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/decisions.md","filePath":"explanation/decisions.md"}'),r={name:"explanation/decisions.md"};function n(s,e,d,c,l,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="decisions" tabindex="-1">Decisions <a class="header-anchor" href="#decisions" aria-label="Permalink to &quot;Decisions&quot;">​</a></h1><p>ADR-lite: decision → alternatives → consequence.</p><h2 id="file-backend-only-in-v1" tabindex="-1">File backend only in v1 <a class="header-anchor" href="#file-backend-only-in-v1" aria-label="Permalink to &quot;File backend only in v1&quot;">​</a></h2><p><strong>Decision:</strong> the only identity backend is <code>file</code> — an <code>identity.txt</code>-style keyfile at the resolved path.</p><p><strong>Alternatives:</strong> ship a keyring backend now; a daemon or remote identity service.</p><p><strong>Consequence:</strong> headless, CI-friendly, zero moving parts — but the key sits on disk (mitigated by <code>0600</code> + the load-time permission warning). The keyring impl exists upstream (<code>cuora-identity-keyring</code>) yet hardcodes the <code>&quot;cuora&quot;</code> service name; a tardigrada backend needs upstream parameterization or a thin local impl. Tracked in <code>project/</code>.</p><h2 id="export-import-over-config-coupling" tabindex="-1"><code>export</code>/<code>import</code> over config coupling <a class="header-anchor" href="#export-import-over-config-coupling" aria-label="Permalink to &quot;`export`/`import` over config coupling&quot;">​</a></h2><p><strong>Decision:</strong> cuora interop is &quot;point both tools at the same keyfile&quot; or &quot;move the keyfile&quot; — no cuora-aware verbs, no shared config discovery.</p><p><strong>Alternatives:</strong> tardigrada reads/writes cuora&#39;s config; a <code>tardigrada cuora</code> subcommand family.</p><p><strong>Consequence:</strong> tardigrada manages <em>generic</em> identities — it never learns what vaults, <code>cuora://</code> refs, or envs are. The integration surface stays one file and two env vars; either tool can be swapped without the other noticing.</p><h2 id="payload-bin-not-a-driver-shim" tabindex="-1">Payload bin, not a driver shim <a class="header-anchor" href="#payload-bin-not-a-driver-shim" aria-label="Permalink to &quot;Payload bin, not a driver shim&quot;">​</a></h2><p><strong>Decision:</strong> the <code>tardigrada</code> command ships as a tamias <code>type: files</code> pack whose <code>bins[].payload</code> is the compiled binary staged by <code>scripts/pack.sh</code> — a real binary on PATH.</p><p><strong>Alternatives:</strong> the org&#39;s usual <code>bins[]</code> shim → <code>tamias-driver-*</code> → engine-lib passthrough (cuora/myco shape); a driver crate.</p><p><strong>Consequence:</strong> no shim→driver→engine indirection for a tool this size — one fewer crate, one fewer process, <code>cargo install --path</code> and <code>tamias install</code> both deploy the same artifact. The cost is a per-triple build artifact (<code>tools/bin/&lt;triple&gt;/</code>, gitignored) instead of a portable shim.</p><h2 id="init-never-clobbers-import-overwrites-deliberately" tabindex="-1"><code>init</code> never clobbers; <code>import</code> overwrites deliberately <a class="header-anchor" href="#init-never-clobbers-import-overwrites-deliberately" aria-label="Permalink to &quot;`init` never clobbers; `import` overwrites deliberately&quot;">​</a></h2><p><strong>Decision:</strong> <code>init</code> is idempotent-safe (second run reports the existing recipient); <code>import</code> replaces whatever identity is configured, with no undo.</p><p><strong>Alternatives:</strong> <code>init --force</code>; <code>import</code> to a staging path.</p><p><strong>Consequence:</strong> the dangerous verb is the explicit one — adopting an existing key is a deliberate act, and pointing <code>import</code> at the wrong file is on the operator (SECURITY.md scope note). <code>export</code> refuses bare-stdout under <code>--json</code> for the same reason: a secret inside a JSON envelope invites accidental logging.</p>',18)])])}const m=o(r,[["render",n]]);export{g as __pageData,m as default};
